        if (el.getAttribute('data-dbt-input') === 'checkbox') {
            el.setAttribute('data-dbt-checked', value ? 'true' : 'false');
        }
         
         
         
        var empty = value === '';
         
         
        el.setAttribute('data-dbt-value',
            empty ? '' : Array.isArray(value) ? JSON.stringify(value) : String(value));
